+
+                final var bytes1 = new BytesArray(new byte[] { (byte) 1 });
+                final var bytes2 = new BytesArray(new byte[] { (byte) 2 });
+                assertTrue(testHarness.tryCompareAndSet(BytesArray.EMPTY, bytes1));
+
+                // show we're looking at the right blob
